<template><section class="page-shell"><header class="page-header"><div><h1>{{ t('workflowNodes.title') }}</h1><p>{{ t('workflowNodes.description') }}</p></div><el-button v-if="auth.hasPermission('automation:workflow:node:create')" type="primary" @click="openCreate">{{ t('workflowNodes.add') }}</el-button></header><el-table :data="templates" v-loading="loading" border><el-table-column prop="name" :label="t('workflowNodes.name')"/><el-table-column prop="code" :label="t('workflowNodes.code')"/><el-table-column prop="nodeType" :label="t('workflowNodes.type')"/><el-table-column prop="functionalCategory" :label="t('workflowNodes.category')"/><el-table-column prop="source" :label="t('workflowNodes.source')"/><el-table-column prop="enabled" :label="t('common.enabled')"/><el-table-column fixed="right" :label="t('common.actions')"><template #default="{row}"><el-button link @click="openEdit(row)">{{ t('common.edit') }}</el-button><el-button v-if="auth.hasPermission('automation:workflow:node:delete')&&!row.systemTemplate" link type="danger" @click="remove(row)">{{ t('common.delete') }}</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="form.id?t('workflowNodes.edit'):t('workflowNodes.add')"><el-form label-position="top"><el-form-item :label="t('workflowNodes.code')"><el-input v-model="form.code" :disabled="form.systemTemplate"/></el-form-item><el-form-item :label="t('workflowNodes.name')"><el-input v-model="form.name"/></el-form-item><el-form-item :label="t('workflowNodes.type')"><el-input v-model="form.nodeType" :disabled="form.systemTemplate"/></el-form-item><el-form-item :label="t('workflowNodes.category')"><el-input v-model="form.functionalCategory"/></el-form-item><el-form-item :label="t('workflowNodes.description')"><el-input v-model="form.description"/></el-form-item><el-form-item :label="t('workflowNodes.defaultConfig')"><el-input v-model="form.configText" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">{{ t('common.cancel') }}</el-button><el-button type="primary" @click="save">{{ t('common.save') }}</el-button></template></el-dialog></section></template><script setup>
import {onMounted,reactive,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {useI18n} from 'vue-i18n';import {http,showHttpError} from '../utils/http';import {useAuthStore} from '../stores/auth';const {t}=useI18n(),auth=useAuthStore(),templates=ref([]),loading=ref(false),visible=ref(false),form=reactive({id:null,code:'',name:'',nodeType:'',description:'',functionalCategory:'',configText:'{}',systemTemplate:false});async function load(){loading.value=true;try{templates.value=(await http.get('/workflow/nodes')).data||[]}catch(e){showHttpError(e)}finally{loading.value=false}}function openCreate(){Object.assign(form,{id:null,code:'',name:'',nodeType:'',description:'',functionalCategory:'',configText:'{}',systemTemplate:false});visible.value=true}function openEdit(r){Object.assign(form,{...r,configText:JSON.stringify(r.config||{},null,2)});visible.value=true}async function save(){try{const b={...form,source:'SYSTEM',config:JSON.parse(form.configText||'{}')};delete b.configText;if(form.id)await http.put('/workflow/nodes/'+form.id,b);else await http.post('/workflow/nodes',b);visible.value=false;await load();ElMessage.success(t('common.success'))}catch(e){showHttpError(e)}}async function remove(r){try{await ElMessageBox.confirm(t('common.confirmDelete',{name:r.name}),t('common.deleteConfirm'));await http.delete('/workflow/nodes/'+r.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')showHttpError(e)}}onMounted(load)</script>